	char *userinfo;
	char *host;
	char *port;
	char *path;
	char *query;
	char *fragment;
	int state;
	int error;

	ParsedURI() { init(); }
	virtual ~ParsedURI() { deinit(); }

	//copy constructor
	ParsedURI(const ParsedURI& uri) { copy(uri); }
	//copy operator
	ParsedURI& operator= (const ParsedURI& uri)
	{
		if (this != &uri)
		{
			deinit();
			copy(uri);
		}

		return *this;
	}

	//move constructor
	ParsedURI(ParsedURI&& uri);
	//move operator
	ParsedURI& operator= (ParsedURI&& uri);

private:
	void init()
	{
		scheme = NULL;
		userinfo = NULL;
		host = NULL;
		port = NULL;
		path = NULL;
		query = NULL;
		fragment = NULL;
		state = URI_STATE_INIT;
		error = 0;
	}

	void deinit()
	{
		free(scheme);
		free(userinfo);
		free(host);
		free(port);
		free(path);
		free(query);
		free(fragment);
	}

	void copy(const ParsedURI& uri);
};

