import os
import random
import struct
from typing import List

# Generator for arbitrary binary strings tailored to exercise many code paths in the
# provided fuzz stubs. We create a corpus of different patterns (ASCII text, URIs,
# JSON, SQL, HTTP snippets, binary lengths, DNS-like names, etc.) and concatenate
# randomly chosen segments to form a single bytes buffer. This buffer can serve as
# FUZZ_PARAM_STR data or file contents for FUZZ_PARAM_FILENAME.

# Utilities to build structured segments

def _rand_ascii(rng: random.Random, min_len=0, max_len=128) -> bytes:
    n = rng.randint(min_len, max_len)
    alphabet = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 _-./:?&=%+#\"'"
    return bytes(rng.choice(alphabet) for _ in range(n))


def _rand_binary(rng: random.Random, min_len=0, max_len=256) -> bytes:
    n = rng.randint(min_len, max_len)
    return rng.randbytes(n) if hasattr(rng, "randbytes") else bytes(rng.getrandbits(8) for _ in range(n))


def _dns_name(rng: random.Random) -> bytes:
    labels = []
    for _ in range(rng.randint(1, 4)):
        L = rng.randint(1, 12)
        label = ''.join(rng.choice('abcdefghijklmnopqrstuvwxyz0123456789-') for _ in range(L))
        label = label.strip('-') or 'a'
        labels.append(label)
    return ('.'.join(labels) + ('' if rng.random() < 0.7 else '.')).encode()


def _http_request(rng: random.Random) -> bytes:
    method = rng.choice([b"GET", b"POST", b"PUT", b"DELETE", b"HEAD"]) 
    path = b"/" + _rand_ascii(rng, 0, 12).replace(b" ", b"_")
    host = _dns_name(rng)
    headers = [b"Host: " + host]
    if rng.random() < 0.5:
        headers.append(b"User-Agent: fuzz/1.0")
    if rng.random() < 0.4:
        headers.append(b"Accept: */*")
    body = b""
    if method in (b"POST", b"PUT") and rng.random() < 0.7:
        body = _rand_ascii(rng, 0, 64)
        headers.append(b"Content-Length: " + str(len(body)).encode())
    req = method + b" " + path + b" HTTP/1.1\r\n" + b"\r\n".join(headers) + b"\r\n\r\n" + body
    return req


def _json_doc(rng: random.Random) -> bytes:
    mode = rng.randrange(4)
    if mode == 0:
        # string
        s = _rand_ascii(rng, 0, 32).decode('latin1').replace('"', '\\"')
        return ('"' + s + '"').encode()
    elif mode == 1:
        return str(rng.randint(-1_000_000, 1_000_000)).encode()
    elif mode == 2:
        k = _rand_ascii(rng, 1, 8).decode('latin1').replace('"', '')
        v = _rand_ascii(rng, 0, 16).decode('latin1').replace('"', '')
        return ("{\"%s\":\"%s\"}" % (k, v)).encode()
    else:
        a = [str(rng.randint(0, 1000)) for _ in range(rng.randint(0, 5))]
        return ("[" + ",".join(a) + "]").encode()


def _mysql_lenenc_string(rng: random.Random) -> bytes:
    payload = _rand_ascii(rng, 0, 64)
    n = len(payload)
    if n <= 251:
        head = bytes([n])
    elif n <= 0xFFFF:
        head = bytes([252]) + struct.pack('<H', n)
    elif n <= 0xFFFFFF:
        head = bytes([253]) + struct.pack('<I', n)[0:3]
    else:
        head = bytes([254]) + struct.pack('<Q', n)
    return head + payload


def _redis_resp_message(rng: random.Random) -> bytes:
    # Simple RESP arrays/inline
    kind = rng.randrange(4)
    if kind == 0:
        # *<n> CRLF $<len> CRLF <data> ...
        nargs = rng.randint(1, 3)
        parts = [b"*" + str(nargs).encode() + b"\r\n"]
        for _ in range(nargs):
            arg = _rand_ascii(rng, 0, 16)
            parts.append(b"$" + str(len(arg)).encode() + b"\r\n" + arg + b"\r\n")
        return b"".join(parts)
    elif kind == 1:
        s = _rand_ascii(rng, 0, 24)
        return b"+" + s + b"\r\n"
    elif kind == 2:
        s = _rand_ascii(rng, 0, 24)
        return b"-" + s + b"\r\n"
    else:
        return b":" + str(rng.randint(-100000, 100000)).encode() + b"\r\n"


def _url(rng: random.Random) -> bytes:
    scheme = rng.choice([b"http", b"https", b"mysql", b"redis", b"dns"])
    host = _dns_name(rng).strip(b".") or b"localhost"
    port = b":" + str(rng.randint(1, 65535)).encode() if rng.random() < 0.7 else b""
    path = b"/" + _rand_ascii(rng, 0, 10).replace(b" ", b"_")
    return scheme + b"://" + host + port + path


def _sql_query(rng: random.Random) -> bytes:
    tbl = _rand_ascii(rng, 3, 8).decode('latin1').replace(' ', '_')
    col = _rand_ascii(rng, 2, 8).decode('latin1').replace(' ', '_')
    val = _rand_ascii(rng, 0, 12).decode('latin1').replace('"', "'")
    kind = rng.randrange(3)
    if kind == 0:
        return f"SELECT {col} FROM {tbl} WHERE {col}='".encode() + val.encode() + b"'" \
               + (b" LIMIT " + str(rng.randint(0, 10)).encode() if rng.random() < 0.5 else b"")
    elif kind == 1:
        return f"INSERT INTO {tbl}({col}) VALUES('".encode() + val.encode() + b"')"
    else:
        return f"UPDATE {tbl} SET {col}='".encode() + val.encode() + b"'"


def _percent_encoded(rng: random.Random, max_len=64) -> bytes:
    def to_hex(x: int) -> int:
        return x + (48 if x < 10 else 55)
    base = _rand_binary(rng, 8, max_len)
    out = bytearray()
    for b in base:
        if rng.random() < 0.4:
            out.extend(b"%" + bytes([to_hex((b >> 4) & 0xF)]) + bytes([to_hex(b & 0xF)]))
        else:
            out.append(b)
        if rng.random() < 0.1:
            # inject invalid escape sometimes
            out.extend(b"%%")
    return bytes(out)


def _ipv4_bytes(rng: random.Random) -> bytes:
    # 4 bytes arbitrary (network order)
    return struct.pack('>I', rng.getrandbits(32))


def _ipv6_bytes(rng: random.Random) -> bytes:
    return (_rand_binary(rng, 16, 16))


def _dns_rr_raw(rng: random.Random) -> bytes:
    # owner, type, class, ttl, rdlength, rdata (simplified textual owner)
    owner = _dns_name(rng)
    rrtype = struct.pack('>H', rng.randint(1, 65535))
    rrclass = struct.pack('>H', rng.randint(1, 65535))
    ttl = struct.pack('>I', rng.randint(0, 86400))
    rdata = _rand_binary(rng, 0, 32)
    rdlen = struct.pack('>H', len(rdata))
    return owner + b"\0" + rrtype + rrclass + ttl + rdlen + rdata


def _tlv(rng: random.Random) -> bytes:
    t = rng.randint(0, 0xFFFFFFFF)
    v = _rand_binary(rng, 0, 64)
    head = struct.pack('<II', t, len(v))
    return head + v


def _compose_segments(rng: random.Random) -> List[bytes]:
    segs: List[bytes] = []
    # Mix different domains to touch many stubs
    if rng.random() < 0.9:
        segs.append(_http_request(rng))
    if rng.random() < 0.7:
        segs.append(_json_doc(rng))
    if rng.random() < 0.8:
        segs.append(_mysql_lenenc_string(rng))
    if rng.random() < 0.8:
        segs.append(_redis_resp_message(rng))
    if rng.random() < 0.8:
        segs.append(_url(rng))
    if rng.random() < 0.6:
        segs.append(_sql_query(rng))
    if rng.random() < 0.7:
        segs.append(_percent_encoded(rng, 72))
    if rng.random() < 0.6:
        segs.append(_dns_name(rng))
    if rng.random() < 0.6:
        segs.append(_ipv4_bytes(rng))
    if rng.random() < 0.5:
        segs.append(_ipv6_bytes(rng))
    if rng.random() < 0.6:
        segs.append(_dns_rr_raw(rng))
    if rng.random() < 0.7:
        segs.append(_tlv(rng))
    # Add some raw ascii/binary noise
    if rng.random() < 0.8:
        segs.append(_rand_ascii(rng, 0, 64))
    if rng.random() < 0.8:
        segs.append(_rand_binary(rng, 0, 64))
    return segs


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Decide how many segment groups to compose (1..4) keeping total <= 4096
    groups = rng.randint(1, 4)
    buf = bytearray()
    for _ in range(groups):
        segs = _compose_segments(rng)
        # Shuffle order to diversify
        rng.shuffle(segs)
        for s in segs:
            # Separate segments by a small delimiter sometimes to help tokenizers
            if rng.random() < 0.3:
                buf.extend(b"\r\n")
            buf.extend(s)
            if len(buf) > 4096:
                break
        if len(buf) > 4096:
            break
    # Ensure non-empty
    if not buf:
        buf.extend(_rand_ascii(rng, 1, 32))
    # Trim to 4096 max
    return bytes(buf[:4096])

import random
import string
from typing import List, Tuple

# We generate valid HTTP requests and responses, including variations:
# - Methods: GET/POST/PUT/DELETE/HEAD/OPTIONS/PATCH
# - Versions: HTTP/1.0, HTTP/1.1
# - Headers including Host, Connection, Content-Length, Transfer-Encoding, Expect, custom headers
# - Bodies: none, fixed length, chunked encoding (with optional trailers)
# - Partial frames: produce only headers, or headers+partial body/chunk to exercise incremental append
# The buffer size is capped by caller (fuzzer trims to 1024), but we cap at 2048 here.

MAX_SIZE = 2048

_methods = [
    "GET", "POST", "PUT", "DELETE", "HEAD", "OPTIONS", "PATCH"
]
_versions = ["HTTP/1.0", "HTTP/1.1"]
_statuses: List[Tuple[int, str]] = [
    (200, "OK"), (201, "Created"), (202, "Accepted"), (204, "No Content"),
    (206, "Partial Content"), (301, "Moved Permanently"), (302, "Found"),
    (304, "Not Modified"), (307, "Temporary Redirect"), (308, "Permanent Redirect"),
    (400, "Bad Request"), (401, "Unauthorized"), (403, "Forbidden"), (404, "Not Found"),
    (405, "Method Not Allowed"), (408, "Request Timeout"), (411, "Length Required"),
    (413, "Payload Too Large"), (414, "URI Too Long"), (415, "Unsupported Media Type"),
    (418, "I'm a teapot"), (425, "Too Early"), (426, "Upgrade Required"),
    (429, "Too Many Requests"), (500, "Internal Server Error"), (501, "Not Implemented"),
    (502, "Bad Gateway"), (503, "Service Unavailable"), (504, "Gateway Timeout")
]

_common_headers = [
    "User-Agent", "Accept", "Accept-Encoding", "Accept-Language",
    "Cache-Control", "Pragma", "Connection", "Upgrade-Insecure-Requests",
    "Content-Type", "Content-Length", "Transfer-Encoding", "Expect",
    "Host", "Range", "If-Modified-Since", "If-None-Match"
]
_content_types = [
    "text/plain; charset=utf-8",
    "application/json",
    "application/x-www-form-urlencoded",
    "text/html; charset=utf-8",
]

_paths = ["/", "/index.html", "/api/v1/resource", "/upload", "/chunk", "/large", "/redirect"]


def _rand_token(r: random.Random, alphabet: str, lo: int, hi: int) -> str:
    n = r.randint(lo, hi)
    return "".join(r.choice(alphabet) for _ in range(n))


def _rand_host(r: random.Random) -> str:
    # Either domain or IPv6 literal
    if r.random() < 0.2:
        # IPv6 literal (simple form)
        parts = [f"{r.randint(0, 65535):x}" for _ in range(8)]
        return f"[{':'.join(parts)}]"
    labels = [
        _rand_token(r, string.ascii_lowercase + string.digits, 1, r.randint(3, 8))
        for _ in range(r.randint(2, 4))
    ]
    return ".".join(labels)


def _rand_query(r: random.Random) -> str:
    if r.random() < 0.4:
        return ""
    pairs = []
    for _ in range(r.randint(1, 4)):
        k = _rand_token(r, string.ascii_lowercase, 1, 6)
        v = _rand_token(r, string.ascii_letters + string.digits + "-_", 0, 8)
        if v:
            pairs.append(f"{k}={v}")
        else:
            pairs.append(k)
    return "?" + "&".join(pairs)


def _make_headers(r: random.Random, base: List[Tuple[str, str]]) -> List[Tuple[str, str]]:
    headers = list(base)
    # Add some random common headers
    extra = r.sample(_common_headers, r.randint(0, min(6, len(_common_headers))))
    for h in extra:
        if any(h.lower() == b[0].lower() for b in headers):
            continue
        if h == "Connection":
            val = r.choice(["keep-alive", "close"])
        elif h == "Accept":
            val = r.choice(["*/*", "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8"])
        elif h == "Accept-Encoding":
            val = r.choice(["gzip, deflate", "identity", "br,gzip"])
        elif h == "Expect":
            val = "100-continue"
        elif h == "Content-Type":
            val = r.choice(_content_types)
        elif h == "Range":
            # Simple byte range
            start = r.randint(0, 100)
            end = start + r.randint(0, 1000)
            val = f"bytes={start}-{end}"
        else:
            val = _rand_token(r, string.ascii_letters + string.digits + "-;=,./ ", 3, 24)
        headers.append((h, val))
    return headers


def _build_request(r: random.Random) -> bytes:
    method = r.choice(_methods)
    path = r.choice(_paths) + _rand_query(r)
    version = r.choice(_versions)

    host = _rand_host(r)
    port_suffix = f":{r.randint(1, 65535)}" if r.random() < 0.2 else ""

    headers: List[Tuple[str, str]] = [("Host", host + port_suffix)]

    body: bytes = b""
    use_chunked = False
    add_body = method in ("POST", "PUT", "PATCH") and r.random() < 0.8

    # Sometimes use Expect: 100-continue to exercise expect handling
    if add_body and r.random() < 0.2:
        headers.append(("Expect", "100-continue"))

    if add_body:
        if r.random() < 0.4:
            # Small JSON
            msg = _rand_token(r, string.ascii_letters + " ", 5, 20)
            msg_escaped = msg.replace("\\", "\\\\").replace("\"", "\\\"")
            body_str = f"{{\"id\":{r.randint(1, 1000)},\"msg\":\"{msg_escaped}\"}}"
            body = body_str.encode()
            headers.append(("Content-Type", "application/json"))
        elif r.random() < 0.5:
            # URL-encoded form
            pairs = []
            for _ in range(r.randint(1, 4)):
                k = _rand_token(r, string.ascii_lowercase, 3, 6)
                v = _rand_token(r, string.ascii_letters + string.digits + "-_", 0, 8)
                pairs.append(f"{k}={v}")
            body = "&".join(pairs).encode()
            headers.append(("Content-Type", "application/x-www-form-urlencoded"))
        else:
            body = _rand_token(r, string.ascii_letters + string.digits + " \n", 0, 256).encode()
            headers.append(("Content-Type", r.choice(_content_types)))

        # Choose between Content-Length or chunked
        use_chunked = r.random() < 0.4
        if use_chunked:
            headers.append(("Transfer-Encoding", "chunked"))
        else:
            headers.append(("Content-Length", str(len(body))))

    # Connection header
    if not any(h.lower() == "connection" for h, _ in headers):
        headers.append(("Connection", r.choice(["keep-alive", "close"])))

    headers = _make_headers(r, headers)

    start_line = f"{method} {path} {version}\r\n"
    head = start_line + "".join(f"{k}: {v}\r\n" for k, v in headers) + "\r\n"

    payload = head.encode()

    if add_body:
        if use_chunked:
            # Build chunked body, optionally fragmented
            chunks: List[bytes] = []
            if len(body) == 0:
                chunk_sizes: List[int] = []
            else:
                remaining = body
                nchunks = r.randint(1, 4)
                for i in range(nchunks - 1):
                    if not remaining:
                        break
                    sz = max(1, len(remaining) // (nchunks - i))
                    cut = r.randint(1, max(1, sz))
                    chunks.append(remaining[:cut])
                    remaining = remaining[cut:]
                if remaining:
                    chunks.append(remaining)
            for c in chunks:
                payload += f"{len(c):X}\r\n".encode() + c + b"\r\n"
            # Optional trailer headers
            if r.random() < 0.3:
                payload += b"0\r\n"
                payload += b"X-Trailer: end\r\n\r\n"
            else:
                payload += b"0\r\n\r\n"
        else:
            payload += body

    # Optionally cut to simulate partial/incremental packet
    if r.random() < 0.35:
        cut = r.randint(1, max(1, min(len(payload), 800)))
        payload = payload[:cut]

    return payload[:MAX_SIZE]


def _build_response(r: random.Random) -> bytes:
    version = r.choice(_versions)
    code, phrase = r.choice(_statuses)

    headers: List[Tuple[str, str]] = []
    body: bytes = b""

    # Decide body presence: no body for 1xx, 204, 304, or HEAD-like behavior sometimes
    no_body = code in range(100, 200) or code in (204, 304) or (r.random() < 0.15)

    if not no_body:
        # Create a body
        if r.random() < 0.5:
            body = _rand_token(r, string.ascii_letters + string.digits + " ", 10, 200).encode()
            headers.append(("Content-Type", "text/plain; charset=utf-8"))
        else:
            # HTML
            title = _rand_token(r, string.ascii_letters + " ", 5, 20)
            body = f"<html><body><h1>{title}</h1></body></html>".encode()
            headers.append(("Content-Type", "text/html; charset=utf-8"))

        # Choose transfer mode
        use_chunked = r.random() < 0.4 and version == "HTTP/1.1"
        if use_chunked:
            headers.append(("Transfer-Encoding", "chunked"))
        else:
            headers.append(("Content-Length", str(len(body))))
    else:
        # Make explicit zero length sometimes
        if r.random() < 0.3:
            headers.append(("Content-Length", "0"))

    # Connection header often present
    headers.append(("Connection", r.choice(["keep-alive", "close"])) )
    headers = _make_headers(r, headers)

    start_line = f"{version} {code} {phrase}\r\n"
    head = start_line + "".join(f"{k}: {v}\r\n" for k, v in headers) + "\r\n"
    payload = head.encode()

    # Append body depending on headers
    if not no_body:
        if any(k.lower() == "transfer-encoding" and "chunked" in v.lower() for k, v in headers):
            # Chunked encode body into few chunks
            chunks: List[bytes] = []
            if len(body) > 0:
                remaining = body
                while remaining:
                    cut = r.randint(1, min(64, len(remaining)))
                    chunks.append(remaining[:cut])
                    remaining = remaining[cut:]
            for c in chunks:
                payload += f"{len(c):X}\r\n".encode() + c + b"\r\n"
            payload += b"0\r\n\r\n"
        else:
            payload += body

    # Optionally send partial for incremental parsing
    if r.random() < 0.3:
        cut = r.randint(1, max(1, min(len(payload), 800)))
        payload = payload[:cut]

    return payload[:MAX_SIZE]


def _maybe_concat_messages(r: random.Random, parts: List[bytes]) -> bytes:
    # Sometimes concatenate multiple messages back-to-back to exercise pipelining
    if r.random() < 0.25 and parts:
        more = r.randint(1, 2)
        for _ in range(more):
            if r.random() < 0.5:
                parts.append(_build_request(r))
            else:
                parts.append(_build_response(r))
    return b"".join(parts)[:MAX_SIZE]


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Choose to generate a request, response, or mixture
    choice = r.random()
    parts: List[bytes] = []
    if choice < 0.45:
        parts.append(_build_request(r))
    elif choice < 0.9:
        parts.append(_build_response(r))
    else:
        parts.append(_build_request(r))
        parts.append(_build_response(r))
    return _maybe_concat_messages(r, parts)

import random
import string
from typing import List, Tuple

# Generator for HTTP request-target/URI bytes suitable for multiple fuzz stubs that expect:
# - http_parser_set_uri: path starting with '/'; printable; modest length
# - protocol::HttpRequest::set_request_uri: valid path, possibly with query
# - WFHttp* stubs build URLs by concatenating to http://127.0.0.1 + path
# So we generate paths that start with '/', include diverse components (segments, queries, matrices),
# and remain <= 256 bytes, ASCII-printable.

SAFE_CHARS_PATH = string.ascii_letters + string.digits + "-._~"  # unreserved per RFC 3986
SAFE_PCT = "%"
SUBDELIMS = "!$&'()*+,;="
PCHAR_EXTRA = SUBDELIMS + ":@"  # allowed in path segment
QUERY_EXTRA = PCHAR_EXTRA + "/?"  # query can include '/' and '?'


def _rand_weighted_choice(rnd: random.Random, items: List[Tuple[str, int]]) -> str:
    total = sum(w for _, w in items)
    pick = rnd.randrange(total)
    acc = 0
    for s, w in items:
        acc += w
        if pick < acc:
            return s
    return items[-1][0]


def _gen_segment(rnd: random.Random) -> str:
    # Generate a single path segment with a mix of chars and percent-encodings
    length = rnd.randint(0, 12)
    seg = []
    for _ in range(length):
        kind = rnd.random()
        if kind < 0.75:
            seg.append(rnd.choice(SAFE_CHARS_PATH + PCHAR_EXTRA))
        elif kind < 0.9:
            # percent-encode a byte from a small interesting set
            b = rnd.choice([0x20, 0x2F, 0x3F, 0x7F, 0x00, rnd.randrange(256)])
            seg.append("%" + format(b, "02X"))
        else:
            # repeated char
            ch = rnd.choice("-_~.")
            seg.append(ch)
    return "".join(seg)


def _gen_query_pairs(rnd: random.Random, max_pairs: int) -> List[Tuple[str, str]]:
    pairs = []
    n = rnd.randint(0, max_pairs)
    for _ in range(n):
        klen = rnd.randint(1, 10)
        vlen = rnd.randint(0, 16)
        def gen_str(L: int, extra: str) -> str:
            s = []
            for _ in range(L):
                kind = rnd.random()
                if kind < 0.8:
                    s.append(rnd.choice(SAFE_CHARS_PATH))
                elif kind < 0.95:
                    s.append(rnd.choice(extra))
                else:
                    b = rnd.randrange(256)
                    s.append("%" + format(b, "02X"))
            return "".join(s)
        k = gen_str(klen, "-._~")
        v = gen_str(vlen, QUERY_EXTRA)
        pairs.append((k, v))
    return pairs


def _compose_query(pairs: List[Tuple[str, str]]) -> str:
    if not pairs:
        return ""
    parts = []
    for k, v in pairs:
        if v == "":
            parts.append(k)
        else:
            parts.append(f"{k}={v}")
    return "?" + "&".join(parts)


def _maybe_matrix_params(rnd: random.Random) -> str:
    # Generate optional ;param=value style matrix params for a path segment
    if rnd.random() < 0.3:
        cnt = rnd.randint(1, 2)
        ps = []
        for _ in range(cnt):
            name = _gen_segment(rnd) or "p"
            val = _gen_segment(rnd)
            if val:
                ps.append(f"{name}={val}")
            else:
                ps.append(name)
        return ";" + ";".join(ps)
    return ""


def _gen_path(rnd: random.Random) -> str:
    # Create a path starting with '/', supporting empty, deep, dot, dotdot, and trailing slash cases.
    depth = rnd.randint(0, 6)
    segments = []
    for i in range(depth):
        choice = _rand_weighted_choice(rnd, [
            ("normal", 8),
            ("dot", 1),
            ("dotdot", 1),
            ("empty", 1),
        ])
        if choice == "dot":
            seg = "."
        elif choice == "dotdot":
            seg = ".."
        elif choice == "empty":
            seg = ""
        else:
            seg = _gen_segment(rnd)
        seg += _maybe_matrix_params(rnd)
        segments.append(seg)
    path = "/" + "/".join(segments)
    # Maybe ensure at least one non-empty segment
    if all(s == "" for s in segments):
        path = "/" + (_gen_segment(rnd) or "index")
    # Optional trailing slash
    if rnd.random() < 0.3:
        if not path.endswith("/"):
            path += "/"
    return path


def _maybe_fragment(rnd: random.Random) -> str:
    if rnd.random() < 0.25:
        flen = rnd.randint(0, 12)
        frag = []
        for _ in range(flen):
            kind = rnd.random()
            if kind < 0.85:
                frag.append(rnd.choice(SAFE_CHARS_PATH + QUERY_EXTRA))
            else:
                frag.append("%" + format(rnd.randrange(256), "02X"))
        return "#" + "".join(frag)
    return ""


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)

    # Choose one of several URI styles to diversify behavior:
    style = _rand_weighted_choice(rnd, [
        ("simple_path", 5),
        ("query_path", 5),
        ("deep_path", 3),
        ("matrix_query", 2),
        ("edge_cases", 2),
    ])

    path = _gen_path(rnd)

    if style == "simple_path":
        query_pairs: List[Tuple[str, str]] = []
    elif style == "query_path":
        query_pairs = _gen_query_pairs(rnd, max_pairs=4)
    elif style == "deep_path":
        # force deeper structure
        path = "/" + "/".join((_gen_segment(rnd) or "a") for _ in range(rnd.randint(3, 8)))
        query_pairs = _gen_query_pairs(rnd, max_pairs=2)
    elif style == "matrix_query":
        # Ensure at least one matrix segment and a query
        path = "/" + ( _gen_segment(rnd) or "p" ) + _maybe_matrix_params(rnd)
        query_pairs = _gen_query_pairs(rnd, max_pairs=5)
    else:  # edge_cases
        # Include dot/dotdot, empty segments, and percent-encoded specials
        segs = ["..", "", _gen_segment(rnd) or "index", "."]
        rnd.shuffle(segs)
        path = "/" + "/".join(segs)
        query_pairs = _gen_query_pairs(rnd, max_pairs=3)

    query = _compose_query(query_pairs)
    frag = _maybe_fragment(rnd)

    uri = path + query + frag

    # Constrain length and ensure ASCII printable by replacing control chars if any (shouldn't occur by construction)
    if len(uri) > 256:
        uri = uri[:256]
    cleaned = []
    for ch in uri:
        o = ord(ch)
        if 0x20 <= o <= 0x7E:
            cleaned.append(ch)
        else:
            cleaned.append('/')
    uri = "".join(cleaned)

    # Ensure starts with '/'
    if not uri.startswith('/'):
        uri = '/' + uri

    return uri.encode('ascii', errors='ignore')
